#include <bits/stdc++.h>
using namespace std;

const long long mod = 998244353;

struct Matrix {
    long long mat[2][2];
    Matrix() {
        memset(mat, 0, sizeof(mat));
    }
    Matrix(long long m[2][2]) {
        for (int i=0; i<2; i++) {
            for (int j=0; j<2; j++) {
                mat[i][j] = m[i][j];
            }
        }
    }
    Matrix pow(long long x) const {
        Matrix res({{1,0},{0,1}});
        Matrix base = *this;
        while (x > 0) {
            if (x & 1) {
                res = res.multiply(base);
            }
            base = base.multiply(base);
            x >>= 1;
        }
        return res;
    }
    Matrix multiply(const Matrix& m) const {
        Matrix r;
        for (int i=0; i<2; i++) {
            for (int j=0; j<2; j++) {
                r.mat[i][j] = 0;
                for (int k=0; k<2; k++) {
                    r.mat[i][j] += mat[i][k] * m.mat[k][j];
                }
                r.mat[i][j] %= mod;
            }
        }
        return r;
    }
};

long long powMod(long long base, long long exp) {
    long long result = 1;
    while (exp > 0) {
        if (exp & 1) {
            result = (result * base) % mod;
        }
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long n, m, L, R;
    cin >> n >> m >> L >> R;
    long long length = R - L + 1;
    if (n % 2 == 1 && m % 2 == 1) {
        cout << powMod((R - L + 1) % mod, n * m) << "\n";
    } else {
        if (length % 2 == 0) {
            long long total = powMod(length % mod, n * m - 1);
            long long result = total * (length / 2) % mod;
            cout << result << "\n";
        } else {
            long long half = length / 2;
            Matrix identity({{1,0},{0,1}});
            Matrix matrix({{half, half + 1},{half + 1, half}});
            Matrix resultMatrix = matrix.pow(n * m);
            cout << resultMatrix.mat[0][0] << "\n";
        }
    }
    return 0;
}

